        if r>start: bands.append((start,r)); start=r+1
    blocks=[]; start=0
    for cc in sorted(div_cols)+[W]:
        if cc>start: blocks.append((start,cc)); start=cc+1
    def bandpix(r0,r1,bi,gg):
        a,b=blocks[bi]
        return [(r,cc) for r in range(r0,r1) for cc in range(a,b) if gg[r][cc]!=0 and gg[r][cc]!=c]
    colordiv={}
    for (r0,r1) in bands:
        for bi in range(1,len(blocks)):
            p1=bandpix(r0,r1,bi-1,g); p2=bandpix(r0,r1,bi,g)
            if p1 and p2:
                col={g[r][cc] for r,cc in p1}|{g[r][cc] for r,cc in p2}
                if len(col)==1: colordiv[col.pop()]=bi
    out=[row[:] for row in g]
    for (r0,r1) in bands:
        for bi,(a,b) in enumerate(blocks):
            pix=bandpix(r0,r1,bi,g)
            if not pix: continue
            col={g[r][cc] for r,cc in pix}
            if len(col)!=1: continue
            col=col.pop()
            if col not in colordiv: continue
            di=colordiv[col]
